29:     private const int MaxOperationIdGenerationAttempts = 5;
30: 
31:     // Demo KYC stub (DESIGN.md decision #6, task file Section 1 step 2): "a hardcoded, clearly-labeled
32:     // demo stub decision ... this is explicitly a demo stub, not real verification." No real KYC provider
33:     // integration exists anywhere in this platform yet - this is not a shortcut unique to the
34:     // Orchestrator, it is the one decided way v1 satisfies IdentityApi's own KYC-verification requirement
35:     // before a mandate/authorization check will treat the customer as eligible at all.
36:     //
37:     // KycTier "Tier2" (T-025 - was "Tier1" until IdentityApi's placeholder KycTierPolicy seed data showed
38:     // that was wrong). IdentityApi's "NG" seed migration only lists "View" for Tier1, so an account opened
39:     // at Tier1 can never pass MandateEligibility's Debit/Credit check - and T-022's own demo scope is
40:     // explicitly "account opening, plain transfer", which needs Debit to work. Tier2 lists
41:     // View/Credit/Debit, so this is the lowest tier that actually supports the demo path it exists for.
42:     // Still a hardcoded, clearly-labeled demo stub decision, not a real KYC-tier policy choice - a real
43:     // deployment would need a real tier decision per customer/jurisdiction, which is exactly what a real
44:     // KYC provider would supply instead of this stub. (Also still assumes the target jurisdiction has a
45:     // Tier2 KycTierPolicy row seeded on the IdentityApi side - true for "NG" in its current seed
46:     // migration, not guaranteed for an arbitrary JurisdictionCode a caller supplies.)
47:     private const string DemoKycTier = "Tier2";
48:     private const string DemoKycVerificationType = "DemoStub";
49:     private const string DemoKycProvider = "OrchestratorDemoStub-NotRealVerification";
50: 
51:     // Fingerprint of the fields that define the operation being started, so a reused idempotency key with
52:     // a different body is detected (same scheme as LedgerApi's AccountService/IdentityApi's
53:     // CustomerService: decision #2 here mirrors decisions #43/#29 there).
54:     private static string HashRequest(StartAccountOpeningRequest request) => Convert.ToBase64String(SHA256.HashData(Encoding.UTF8.GetBytes(
55:         JsonSerializer.Serialize(new[]
56:         {
57:             request.FullName,
58:             request.JurisdictionCode,
59:             request.CustomerReference ?? "",
60:             request.Email ?? "",
61:             request.PhoneNumber ?? "",
62:             request.AccountName,
63:             request.AccountType,
64:             request.CurrencyCode,
65:         }))));
66: 
67:     private static AccountOpeningResponse ToResponse(AccountOpening opening) => new(
68:         opening.OperationId,
69:         opening.Status.ToString(),
70:         opening.CurrentStep.ToString(),
71:         opening.CustomerId,
72:         opening.LedgerAccountId,
73:         opening.FailureReason,
74:         opening.CreatedAt,
75:         opening.CompletedAt);
76: 
77:     public async Task<AccountOpeningResponse> StartAsync(StartAccountOpeningRequest request, CancellationToken cancellationToken = default)
78:     {
79:         var clientId = currentClient.ClientId;
80:         var requestHash = HashRequest(request);
81: 
82:         for (var attempt = 1; attempt <= MaxOperationIdGenerationAttempts; attempt++)
83:         {
84:             var now = DateTimeOffset.UtcNow;
85: 
86:             var opening = new AccountOpening
87:             {
88:                 OperationId = OperationIdGenerator.Generate(),
89:                 IdempotencyKey = request.IdempotencyKey,
90:                 InitiatedBy = clientId,
91:                 RequestHash = requestHash,
92:                 FullName = request.FullName,
93:                 JurisdictionCode = request.JurisdictionCode,
94:                 CustomerReference = request.CustomerReference,
95:                 Email = request.Email,
96:                 PhoneNumber = request.PhoneNumber,
97:                 AccountName = request.AccountName,
98:                 AccountType = request.AccountType,
99:                 CurrencyCode = request.CurrencyCode,
100:                 CurrentStep = AccountOpeningStep.CreateCustomer,
101:                 Status = AccountOpeningStatus.InProgress,
102:                 CreatedAt = now,
103:             };
104: 
105:             await dbContext.AccountOpenings.AddAsync(opening, cancellationToken);
106: 
107:             var audit = auditLogger.Record(new AuditLog
108:             {
109:                 Action = AuditActions.AccountOpeningStarted,
110:                 EntityType = nameof(AccountOpening),
111:                 EntityId = opening.OperationId,
112:                 Status = opening.Status.ToString(),
113:             });
114: 
115:             try
116:             {
117:                 await dbContext.SaveChangesAsync(cancellationToken);
118:             }
119:             catch (DbUpdateException ex) when (ex.InnerException is PostgresException { SqlState: "23505" } pgEx)
120:             {
121:                 // Dependents before principals (EF navigation-fixup ordering - mirrors CustomerService).
122:                 dbContext.Entry(opening).State = EntityState.Detached;
123:                 dbContext.Entry(audit).State = EntityState.Detached;
124: 
125:                 if (pgEx.ConstraintName == "ix_account_openings_initiated_by_idempotency_key")
126:                 {
127:                     var existing = await dbContext.AccountOpenings.AsNoTracking().FirstOrDefaultAsync(
128:                         o => o.InitiatedBy == clientId && o.IdempotencyKey == request.IdempotencyKey, cancellationToken);
129: 
130:                     if (existing is null)
131:                         throw new InvalidOperationException("Error retrieving the result of the existing idempotency key.");
132: 
133:                     // Same key, different request: refuse rather than report the old operation as this
134:                     // one's (409, ARCHITECTURE.md Section 5).
135:                     if (existing.RequestHash != requestHash)
136:                         throw new DuplicateIdempotencyKeyException(
137:                             $"Idempotency key '{request.IdempotencyKey}' was already used for a different request.");
138: 
139:                     // Same key, same request: this is a retry of an already-started (or already-finished)
140:                     // operation. Resume/no-op through the same path POST .../retry uses, rather than
141:                     // silently returning a possibly-stale snapshot.
142:                     return await RunFromCurrentStepAsync(await GetTrackedAsync(existing.OperationId, cancellationToken), cancellationToken);
143:                 }
144:                 // Otherwise the collision was on OperationId: loop around and try another one.
145:                 continue;
146:             }
147: 
148:             return await RunFromCurrentStepAsync(opening, cancellationToken);
149:         }
150: 
151:         throw new InvalidOperationException($"Could not allocate a unique OperationId after {MaxOperationIdGenerationAttempts} attempts.");
152:     }
153: 
154:     public async Task<AccountOpeningResponse?> GetAsync(string operationId, CancellationToken cancellationToken = default)
155:     {
156:         var opening = await dbContext.AccountOpenings.AsNoTracking()
157:             .FirstOrDefaultAsync(o => o.OperationId == operationId, cancellationToken);
158:         return opening is null ? null : ToResponse(opening);
159:     }
160: 
161:     public async Task<AccountOpeningResponse> RetryAsync(string operationId, CancellationToken cancellationToken = default)
162:     {
163:         var opening = await GetTrackedAsync(operationId, cancellationToken);
164:         return await RunFromCurrentStepAsync(opening, cancellationToken);
165:     }
166: 
167:     private async Task<AccountOpening> GetTrackedAsync(string operationId, CancellationToken cancellationToken) =>
168:         await dbContext.AccountOpenings.FirstOrDefaultAsync(o => o.OperationId == operationId, cancellationToken)
169:             ?? throw new AccountOpeningNotFoundException($"Account opening '{operationId}' was not found.");
170: 
171:     // DESIGN.md Section 1.4: "re-runs the sequence from CurrentStep onward ... every downstream call uses
172:     // a derived, deterministic idempotency key ... so a step that already succeeded is a safe no-op if
173:     // accidentally re-invoked." Each `if` below falls through to the next once its step's CurrentStep is
174:     // advanced, so a fresh Start runs steps 1-4 in one pass; a retry starting mid-sequence only enters the
175:     // blocks at or after the stored CurrentStep - the skipped blocks are never reached, which is what the
176:     // task file's "verify with a call-count assertion" tests check.
177:     private async Task<AccountOpeningResponse> RunFromCurrentStepAsync(AccountOpening opening, CancellationToken cancellationToken)
178:     {
179:         // Decision #2 / task file: "If Status is already Complete, this is a no-op that just returns the
180:         // current state (don't error - matches ... Customer.Suspend/Mandate.Revoke['s]... 'repeat of an
181:         // already-successful thing is idempotent' convention."
182:         if (opening.Status == AccountOpeningStatus.Complete)
183:         {
184:             return ToResponse(opening);
185:         }
186: 
187:         opening.Status = AccountOpeningStatus.InProgress;
188:         opening.FailureReason = null;
189: 
190:         try
191:         {
192:             if (opening.CurrentStep == AccountOpeningStep.CreateCustomer)
193:             {
194:                 var customer = await identityApiClient.CreateCustomerAsync(
195:                     new CreateCustomerRequest(
196:                         opening.FullName, opening.JurisdictionCode, opening.CustomerReference, opening.Email, opening.PhoneNumber,
197:                         $"orch:{opening.OperationId}:create-customer"),
198:                     cancellationToken);
199:                 opening.CustomerId = customer.CustomerId;
200:                 opening.CurrentStep = AccountOpeningStep.VerifyKyc;
201:                 await SaveStepProgressAsync(opening, "CreateCustomer succeeded", cancellationToken);
202:             }
203: 
204:             if (opening.CurrentStep == AccountOpeningStep.VerifyKyc)
205:             {
206:                 await identityApiClient.RecordKycDecisionAsync(
207:                     opening.CustomerId!,
208:                     new KycDecisionRequest(
209:                         KycStatus: "Verified", KycTier: DemoKycTier, VerificationType: DemoKycVerificationType,
210:                         Provider: DemoKycProvider, ProviderReference: null, ResultCode: "DEMO-AUTO-APPROVED", ExpiresAt: null),
211:                     cancellationToken);
212:                 opening.CurrentStep = AccountOpeningStep.CreateLedgerAccount;
213:                 await SaveStepProgressAsync(opening, "VerifyKyc succeeded (demo stub)", cancellationToken);
214:             }
215: 
216:             if (opening.CurrentStep == AccountOpeningStep.CreateLedgerAccount)
217:             {
218:                 var account = await ledgerApiClient.CreateAccountAsync(
219:                     new CreateAccountRequest(
220:                         opening.AccountName, opening.AccountType, opening.CurrencyCode,
221:                         $"orch:{opening.OperationId}:create-account"),
222:                     cancellationToken);
223:                 opening.LedgerAccountId = account.AccountNumber;
224:                 opening.CurrentStep = AccountOpeningStep.AttachMandate;
225:                 await SaveStepProgressAsync(opening, "CreateLedgerAccount succeeded", cancellationToken);
226:             }
227: 
228:             if (opening.CurrentStep == AccountOpeningStep.AttachMandate)
229:             {
230:                 try
231:                 {
232:                     await identityApiClient.AttachMandateAsync(
233:                         opening.CustomerId!,
234:                         new AttachMandateRequest(opening.LedgerAccountId!, ["View", "Debit", "Credit"]),
235:                         cancellationToken);
236:                 }
237:                 catch (MandateAlreadyAttachedException)
238:                 {
239:                     // Already attached by an earlier attempt at this same step (Exceptions/
240:                     // MandateAlreadyAttachedException.cs) - treated as success on retry, not re-thrown.
241:                 }
242:                 opening.CurrentStep = AccountOpeningStep.Complete;
243:                 await SaveStepProgressAsync(opening, "AttachMandate succeeded", cancellationToken);
244:             }
245: 
246:             opening.Status = AccountOpeningStatus.Complete;
247:             opening.CompletedAt = DateTimeOffset.UtcNow;
248:             auditLogger.Record(new AuditLog
249:             {
250:                 Action = AuditActions.AccountOpeningCompleted,
251:                 EntityType = nameof(AccountOpening),
252:                 EntityId = opening.OperationId,
253:                 Status = opening.Status.ToString(),
254:             });
255:             await dbContext.SaveChangesAsync(cancellationToken);
256:         }
257:         catch (Exception ex)
258:         {
259:             // DESIGN.md 1.11/task file: "If any step throws, catch it, set Status = Failed,
260:             // FailureReason, leave CurrentStep at whichever step failed, and return a response ... do not
261:             // let an unhandled exception escape as a bare 500 with no operation record."
262:             opening.Status = AccountOpeningStatus.Failed;
263:             opening.FailureReason = ex.Message;
264: 
265:             auditLogger.Record(new AuditLog
266:             {
267:                 Action = AuditActions.AccountOpeningStepFailed,
268:                 EntityType = nameof(AccountOpening),
269:                 EntityId = opening.OperationId,
270:                 Status = opening.Status.ToString(),
271:                 Details = $"Step {opening.CurrentStep}: {ex.Message}",
272:             });
273:             await dbContext.SaveChangesAsync(cancellationToken);
274:         }
275: 
276:         return ToResponse(opening);
277:     }
278: 
279:     private Task SaveStepProgressAsync(AccountOpening opening, string details, CancellationToken cancellationToken)
280:     {
281:         auditLogger.Record(new AuditLog
282:         {
283:             Action = AuditActions.AccountOpeningStepSucceeded,
284:             EntityType = nameof(AccountOpening),
285:             EntityId = opening.OperationId,
286:             Status = opening.CurrentStep.ToString(),
287:             Details = details,
288:         });
289:         return dbContext.SaveChangesAsync(cancellationToken);
290:     }
291: }

